head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.procJob = "";             // 진행 중인 처리명 (완료·실패 메시지 인자) — 원본 procJob(선언 없이 쓰던 전역)
scwin.searchDd = "";            // 마지막으로 조회한 마감일 — 원본 vSearchDate
scwin.isLoaded = false;         // 단계별 목록 6종이 모두 조회됐는지 — 원본 loading1~6
scwin.JOBTITL_CHRG = "03";      // 직책코드 — 담당자
// 단계별 목록 6종 — 조회 서브미션(경로 리터럴), 목록, 그리드, 건수, 단계명(중복 안내·엑셀 시트명)
scwin.STEP_LIST = [
    {
        sbmOptions : { id : "sbm_firstDetect", action : "/api/listing/lstproc/pf/invst-warn/select-list-first-detect", method : "get", ref : "dma_searchReq", target : "dlt_firstDetect=body", isProcessMsg : false },
        dlt : "dlt_firstDetect", grid : "grd_List1", cnt : "txb_cnt1", name : "최초적출"
    },
    {
        sbmOptions : { id : "sbm_noti", action : "/api/listing/lstproc/pf/invst-warn/select-list-noti", method : "get", ref : "dma_searchReq", target : "dlt_noti=body", isProcessMsg : false },
        dlt : "dlt_noti", grid : "grd_List2", cnt : "txb_cnt2", name : "지정예고"
    },
    {
        sbmOptions : { id : "sbm_extn", action : "/api/listing/lstproc/pf/invst-warn/select-list-extn", method : "get", ref : "dma_searchReq", target : "dlt_extn=body", isProcessMsg : false },
        dlt : "dlt_extn", grid : "grd_List3", cnt : "txb_cnt3", name : "지정연장"
    },
    {
        sbmOptions : { id : "sbm_design", action : "/api/listing/lstproc/pf/invst-warn/select-list-design", method : "get", ref : "dma_searchReq", target : "dlt_design=body", isProcessMsg : false },
        dlt : "dlt_design", grid : "grd_List4", cnt : "txb_cnt4", name : "지정"
    },
    {
        sbmOptions : { id : "sbm_release", action : "/api/listing/lstproc/pf/invst-warn/select-list-release", method : "get", ref : "dma_searchReq", target : "dlt_release=body", isProcessMsg : false },
        dlt : "dlt_release", grid : "grd_List5", cnt : "txb_cnt5", name : "지정해제"
    },
    {
        sbmOptions : { id : "sbm_trdHalt", action : "/api/listing/lstproc/pf/invst-warn/select-list-trd-halt", method : "get", ref : "dma_searchReq", target : "dlt_trdhalt=body", isProcessMsg : false },
        dlt : "dlt_trdhalt", grid : "grd_List6", cnt : "txb_cnt6", name : "매매거래정지"
    }
];

// 원본 : /pf/ULDSTF09350.gfm (투자유의 마감처리) — gfm 은 저장소에 없고, W-Craft 1차 변환에 API 적용까지 마친 개발 사본으로 분석했다.
/*
 * 화면 동작
 *  - 마감일의 투자유의종목 단계별(최초적출·지정예고·지정연장·지정·지정해제·매매거래정지) 마감대상을 그리드 6개에 보여 준다.
 *  - 마감상태(담당자·팀장 확인시각)와 시장정보 배치실행 여부를 함께 보여 준다.
 *  - 당일 마감일에만 [담당자 확인] → [팀장승인] 순서로 마감한다. 팀장승인은 6개 목록 전 행을 보낸다.
 *  - 같은 단계에 같은 종목이 두 번 있으면 조회 뒤 안내한다.
 *  - 통신·데이터 정의는 개발 사본에 적용된 /api/listing/lstproc/pf/invst-warn/ API 10종 기준(명세로 간주).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09350/ULDSTF09350.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(개발 사본은 onpageload 안에 직접 있었다 — §8 #1). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09350.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 세션 정보 → init 바인딩 → 버튼 초기 상태(잠금) → 마감일 = 오늘 → 조회. (원본 onpageload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 세션 — 원본 pJobTitl
    scwin.jobTitl = $c.session.getUserInfo("jobtitl") ?? "";

    // 2) init 바인딩 (전환 규칙 22·37) — 마감일 단일 달력, 조회 영역 Enter 키
    $c.date.checkCalendarFormat(edt_ConfirmDate, "yyyyMMdd");
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 버튼 초기 상태 — 마감상태 조회 뒤 정한다(그 전까지 잠금)
    btn_Revw.setDisabled(true);
    btn_BosApv.setDisabled(true);

    // 4) 마감일 = 오늘 → 조회 (원본 setValue(오늘) + listSync)
    dma_searchReq.set("trdDd", $c.date.getServerDateTime("yyyyMMdd"));
    await scwin.listSync();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭(조회 영역 Enter 키 포함). (원본 btn_Search_onclick → listSync — §5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09350.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.edt_ConfirmDate_onblur
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감일 포커스 이탈 — 마감일이 마지막 조회와 다를 때만 다시 조회한다(원본은 값이 그대로여도 포커스가 빠질 때마다 조회). (원본 edt_ConfirmDate_onkillfocus — §4, §8 #7)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.edt_ConfirmDate_onblur = async function (e) {
    try {
        if (dma_searchReq.get("trdDd") === scwin.searchDd) return;
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09350.edt_ConfirmDate_onblur" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 클릭. (원본 btn_Excel_onclick → excelDown — §6.6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Excel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09350.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Revw_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [담당자 확인] 클릭. (원본 btn_Revw_onclick → revw — §6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Revw_onclick = async function (e) {
    try {
        await scwin.review();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09350.btn_Revw_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_BosApv_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [팀장승인] 클릭. (원본 btn_BosApv_onclick → aprv — §6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_BosApv_onclick = async function (e) {
    try {
        await scwin.approve();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09350.btn_BosApv_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectClosingStatus
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감상태(담당자·팀장 이름과 확인시각) 조회 뒤 버튼 상태를 정한다. (원본 clslogSync + dts_sendLog_OnLoadCompleted — §5.1)
 * @param {String} basDd 마감일(yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.selectClosingStatus = async function (basDd) {
    dma_closingStatus.setEmptyValue();

    const sbmOptions = {
        id : "sbm_closingStatus",
        action : "/api/listing/lstproc/pf/invst-warn/closing-status",
        method : "get",
        target : "dma_closingStatus=body",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions, { basDd : basDd });
    scwin.applyButtonState();
};

/**
 * @method
 * @name scwin.selectBatchStatus
 * @author Inswave
 * @date 2026. 10. 30
 * @description 시장정보 배치실행 여부 조회 — 최종마감여부(clsYn)를 화면 하단에 보인다. (원본 getJungBoBatch — §5.2)
 * @param {String} toDay 마감일(yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.selectBatchStatus = async function (toDay) {
    dma_checkMdBatchClosing.setEmptyValue();

    const sbmOptions = {
        id : "sbm_checkMdBatchClosing",
        action : "/api/listing/lstproc/pf/invst-warn/check-md-batch-closing",
        method : "get",
        target : "dma_checkMdBatchClosing=body",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions, { toDay : toDay });
};

/**
 * @method
 * @name scwin.selectStepList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 단계별 목록 하나를 조회하고 건수를 보인다. 실패하면 원본 OnLoadError 안내를 띄운다. (원본 listDtl + dts_*_OnLoadCompleted·OnLoadError — §5.3)
 * @param {Object} step scwin.STEP_LIST 의 항목
 * @returns {Boolean} 조회에 성공하면 true
 * @hidden N
 */
scwin.selectStepList = async function (step) {
    const dlt = $p.getComponentById(step.dlt);
    dlt.removeAll();

    // 공통 executeDynamic 은 넘긴 옵션 객체를 고친다(target 등) — 다음 조회에 영향이 없도록 사본을 넘긴다
    const result = await $c.sbm.executeDynamic({ ...step.sbmOptions });
    $c.stf.fillGridHeaderTotalCnt(dlt.getRowCount(), $p.getComponentById(step.cnt));

    if (!result?.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.reviewTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 담당자 확인 요청. 성공이면 완료 안내 후 다시 조회하고, 실패면 실패 안내만 한다. (원본 trsRevw + trs_revw_OnSuccess·OnFail — §5.4)
 * @returns
 * @hidden N
 */
scwin.reviewTrs = async function () {
    dma_reviewReq.set("completeYn", true);
    dma_reviewReq.set("completeCtnt", "확인완료");

    const sbmOptions = {
        id : "sbm_review",
        action : "/api/listing/lstproc/pf/invst-warn/review",
        method : "post",
        ref : "dma_reviewReq",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀 (원본 연속 클릭)

    // TODO: 응답 정의가 없어 성공은 success 로만 판정한다 — 업무 결과 코드가 있는지 확인 (§10 #2)
    if (!result?.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    await scwin.listSync();
};

/**
 * @method
 * @name scwin.approveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 팀장승인 요청 — 단계별 목록 6종 전 행을 한 목록으로 보낸다. 성공이면 완료 안내 후 다시 조회한다. (원본 trsAprv + trs_aprv_OnSuccess·OnFail — §5.5)
 * @returns
 * @hidden N
 */
scwin.approveTrs = async function () {
    const aprvList = scwin.STEP_LIST.flatMap(step => $p.getComponentById(step.dlt).getAllJSON());
    dma_approveReq.set("pfInvstWarnClosingHistList", aprvList);

    const sbmOptions = {
        id : "sbm_approve",
        action : "/api/listing/lstproc/pf/invst-warn/approve",
        method : "post",
        ref : "dma_approveReq",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;

    // TODO: 응답 정의가 없어 성공은 success 로만 판정한다 — 업무 결과 코드가 있는지 확인 (§10 #2)
    if (!result?.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    await scwin.listSync();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.listSync
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 마감상태 → 시장정보 배치 → 단계별 목록 6종을 차례로 조회하고, 모두 성공하면 같은 단계의 중복 종목을 점검한다. (원본 listSync — §5)
 * @returns
 * @hidden N
 */
scwin.listSync = async function () {
    if (!await scwin.validateSearch()) return;

    const searchDd = dma_searchReq.get("trdDd");
    scwin.isLoaded = false;
    scwin.searchDd = searchDd;

    await scwin.selectClosingStatus(searchDd);
    await scwin.selectBatchStatus(searchDd);

    let isAllLoaded = true;
    for (const step of scwin.STEP_LIST) {
        if (!await scwin.selectStepList(step)) isAllLoaded = false;
    }

    scwin.isLoaded = isAllLoaded;
    if (isAllLoaded) await scwin.checkDupList();
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 전 마감일 확인 — 비었거나 8자리가 아니면 안내한다. (원본 dateErrCheck — §6.1)
 * @returns {Boolean} 조회 가능하면 true
 * @hidden N
 */
scwin.validateSearch = async function () {
    const trdDd = String(dma_searchReq.get("trdDd") ?? "");
    if (trdDd.length !== 8) {
        await $c.win.alert("마감일을 입력하세요.");
        edt_ConfirmDate.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.checkIsClose
 * @author Inswave
 * @date 2026. 10. 30
 * @description 마감 가능 여부 — 마감일과 마지막 조회일이 모두 오늘이어야 한다. (원본 chkIsClose — §6.2)
 * @returns {Boolean} 마감할 수 있으면 true
 * @hidden N
 */
scwin.checkIsClose = async function () {
    const curDd = $c.date.getServerDateTime("yyyyMMdd");
    if (dma_searchReq.get("trdDd") !== curDd || scwin.searchDd !== curDd) {
        await $c.win.alert("당일날짜만 마감가능합니다. 마감일을 확인하세요");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.review
 * @author Inswave
 * @date 2026. 10. 30
 * @description 담당자 확인 — 당일 확인 후 확인창에서 예를 고르면 요청한다. (원본 revw — §6.3)
 * @returns
 * @hidden N
 */
scwin.review = async function () {
    scwin.procJob = "담당자 확인";
    if (!await scwin.checkIsClose()) return;
    if (!await $c.win.confirm(scwin.procJob + " 마감처리 하시겠습니까?")) return;

    await scwin.reviewTrs();
};

/**
 * @method
 * @name scwin.approve
 * @author Inswave
 * @date 2026. 10. 30
 * @description 팀장승인 — 목록 6종이 모두 조회됐고, 당일이고, 담당자 확인이 끝났을 때만 확인창을 거쳐 요청한다. (원본 aprv — §6.4)
 * @returns
 * @hidden N
 */
scwin.approve = async function () {
    if (!scwin.isLoaded) {
        await $c.win.alert("데이터가 로딩중입니다. 로딩후에 승인가능합니다.");
        return;
    }
    if (!await scwin.checkIsClose()) return;

    scwin.procJob = "팀장승인";
    if ($c.util.isEmpty(dma_closingStatus.get("chrgApprovTm"))) {
        await $c.win.alert("담당자확인 완료 후 승인처리 가능합니다.");
        return;
    }
    if (!await $c.win.confirm(scwin.procJob + " 마감처리 하시겠습니까?")) return;

    await scwin.approveTrs();
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 담당자 확인·팀장승인 버튼 상태 — 담당자(직책 03)는 담당자 확인만, 그 밖(팀장)은 둘 다 확인시각이 없을 때 연다. (원본 buttonSetDis — §6.5)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    const isReviewed = !$c.util.isEmpty(dma_closingStatus.get("chrgApprovTm"));
    const isApproved = !$c.util.isEmpty(dma_closingStatus.get("teamleadrApprovTm"));

    btn_Revw.setDisabled(isReviewed);
    if (scwin.jobTitl === scwin.JOBTITL_CHRG) {
        btn_BosApv.setDisabled(true);       // 담당자는 팀장승인을 할 수 없다
    } else {
        btn_BosApv.setDisabled(isApproved);
    }
};

/**
 * @method
 * @name scwin.checkDupList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 단계마다 같은 종목이 두 번 이상 있으면 단계별로 안내한다. (원본 closeLoading → checkDupList — §6.7)
 * @returns
 * @hidden N
 */
scwin.checkDupList = async function () {
    for (const step of scwin.STEP_LIST) {
        if (scwin.hasDupIsu($p.getComponentById(step.dlt))) {
            await $c.win.alert("투자유의종목 " + step.name + " 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
        }
    }
};

/**
 * @method
 * @name scwin.hasDupIsu
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록에 같은 종목코드가 두 번 이상 있는지. (원본 loopDataSet — 대문자 키·1부터 세는 행 번호 결함 수정, §8 #4)
 * @param {Object} dlt 단계별 목록 dataList
 * @returns {Boolean} 중복이 있으면 true
 * @hidden N
 */
scwin.hasDupIsu = function (dlt) {
    const isuCds = dlt.getAllJSON().map(row => row.isuCd);
    return new Set(isuCds).size !== isuCds.length;
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 행이 있는 단계의 그리드를 하나씩 내려받는다(단계마다 파일 하나).
 * 파일명은 {menuId}_{원본 이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42). (원본 excelDown — §6.6)
 * @returns
 * @hidden N
 */
scwin.excelDown = function () {
    const prefix = $c.win.getProgramId() + "_";
    const suffix = "_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx";

    for (const step of scwin.STEP_LIST) {
        if ($p.getComponentById(step.dlt).getRowCount() === 0) continue;
        $c.data.downloadGridViewExcel($p.getComponentById(step.grid), { fileName : prefix + "투자유의종목_" + step.name + suffix, sheetName : step.name });
    }
};
